@app.get("/health")
async def health(db: Session = Depends(get_db)):
    try:
        db.execute(text("SELECT 1"))
        db_status = "healthy"
    except Exception as exc:
        db_status = f"unhealthy: {str(exc)}"

    try:
        from app.lock_service import redis_client
        redis_client.ping()
        redis_status = "healthy"
    except Exception as exc:
        redis_status = f"unhealthy: {str(exc)}"

    return {
        "status": "healthy",
        "database": db_status,
        "redis": redis_status,
    }


@app.post("/events", response_model=EventResponse, status_code=201)
async def create_event(event: EventCreate, db: Session = Depends(get_db)):
    db_event = Event(**event.model_dump())
    db.add(db_event)
    db.commit()
    db.refresh(db_event)
    return db_event


@app.get("/events", response_model=List[EventResponse])
async def list_events(db: Session = Depends(get_db)):
    return db.query(Event).order_by(Event.event_date).all()


@app.get("/events/{event_id}", response_model=EventResponse)
async def get_event(event_id: str, db: Session = Depends(get_db)):
    event = db.query(Event).filter(Event.event_id == event_id).first()
    if not event:
        raise HTTPException(status_code=404, detail="Event not found")
    return event


@app.post("/events/{event_id}/seats", response_model=SeatResponse, status_code=201)
async def create_seat(event_id: str, seat: SeatCreate, db: Session = Depends(get_db)):
    event = db.query(Event).filter(Event.event_id == event_id).first()
    if not event:
        raise HTTPException(status_code=404, detail="Event not found")

    db_seat = Seat(event_id=event_id, seat_number=seat.seat_number, price=seat.price)
    db.add(db_seat)
    db.commit()
    db.refresh(db_seat)
    return db_seat


@app.get("/events/{event_id}/seats", response_model=List[SeatResponse])
async def list_seats(event_id: str, status: Optional[str] = None, db: Session = Depends(get_db)):
    query = db.query(Seat).filter(Seat.event_id == event_id)
    if status:
        query = query.filter(Seat.status == status)
    return query.order_by(Seat.seat_number).all()


@app.get("/events/{event_id}/seats/{seat_id}", response_model=SeatResponse)
async def get_seat(event_id: str, seat_id: str, db: Session = Depends(get_db)):
    seat = db.query(Seat).filter(Seat.event_id == event_id, Seat.seat_id == seat_id).first()
    if not seat:
        raise HTTPException(status_code=404, detail="Seat not found")
    return seat


@app.post("/holds", response_model=HoldResponse, status_code=201)
async def create_hold(request: HoldCreate, db: Session = Depends(get_db)):
    lock_resource = f"seat-hold:{request.event_id}:{request.seat_id}"

    try:
        with acquire_lock(lock_resource, timeout=5):
            seat = (
                db.query(Seat)
                .filter(
                    Seat.event_id == request.event_id,
                    Seat.seat_id == request.seat_id,
                )
                .first()
            )

            if not seat:
                raise HTTPException(status_code=404, detail="Seat not found")

            seat_status = seat.status.value if hasattr(seat.status, "value") else str(seat.status)
            if str(seat_status).lower() == "booked":
                raise HTTPException(status_code=409, detail="Seat already booked")

            created, hold = HoldService.create_hold(
                user_id=str(request.user_id),
                event_id=str(request.event_id),
                seat_id=str(request.seat_id),
                ttl_seconds=request.ttl_seconds,
            )

            if not created:
                raise HTTPException(status_code=409, detail="Seat already held")

        await manager.broadcast_to_event(
            event_id=str(request.event_id),
            message={
                "type": "seat_update",
                "action": "held",
                "event_id": str(request.event_id),
                "seat_id": str(request.seat_id),
                "seat_number": seat.seat_number,
                "status": "held",
                "held_by": str(request.user_id),
                "expires_at": hold["expires_at"],
            },
        )

        return HoldResponse(**hold)

    except HTTPException:
        raise
    except Exception as exc:
        raise HTTPException(status_code=500, detail=f"Hold creation failed: {str(exc)}")


@app.delete("/holds/{hold_token}")
async def release_hold(hold_token: str):
    hold = HoldService.release_hold(hold_token)
    if not hold:
        raise HTTPException(status_code=404, detail="Hold not found")

    await manager.broadcast_to_event(
        event_id=str(hold["event_id"]),
        message={
            "type": "seat_update",
            "action": "released",
            "event_id": str(hold["event_id"]),
            "seat_id": str(hold["seat_id"]),
            "status": "available",
        },
    )

    return {"message": "Hold released"}


@app.post("/bookings", response_model=BookingResponse, status_code=201)
async def create_booking_with_payment(
    booking_request: BookingWithPaymentCreate,
    db: Session = Depends(get_db),
):
    payment_method = normalize_payment_method(booking_request.payment_method)
    payment_details = {}

    if payment_method in {"credit_card", "debit_card"}:
        if not booking_request.card_details:
            raise HTTPException(status_code=400, detail="Card details required")
        payment_details = {
            "card_number": booking_request.card_details.card_number,
            "card_holder_name": booking_request.card_details.card_holder_name,
            "expiry_month": booking_request.card_details.expiry_month,
            "expiry_year": booking_request.card_details.expiry_year,
            "cvv": booking_request.card_details.cvv,
        }
    elif payment_method == "upi":
        if not booking_request.upi_details:
            raise HTTPException(status_code=400, detail="UPI details required")
        payment_details = {"upi_id": booking_request.upi_details.upi_id}
    elif payment_method == "net_banking":
        if not booking_request.netbanking_details:
            raise HTTPException(status_code=400, detail="Net banking details required")
        payment_details = {"bank_code": booking_request.netbanking_details.bank_code}
    elif payment_method == "wallet":
        if not booking_request.wallet_details:
            raise HTTPException(status_code=400, detail="Wallet details required")
        payment_details = {
            "wallet_id": booking_request.wallet_details.wallet_id,
            "wallet_provider": booking_request.wallet_details.wallet_provider,
        }
    else:
        raise HTTPException(status_code=400, detail=f"Unsupported payment method: {payment_method}")

    booking, payment, result = PaymentService.create_booking_with_payment(
        db=db,
        user_id=str(booking_request.user_id),
        event_id=str(booking_request.event_id),
        seat_id=str(booking_request.seat_id),
        payment_method=payment_method,
        payment_details=payment_details,
        hold_token=booking_request.hold_token,
        idempotency_key=booking_request.idempotency_key,
    )

    logger.info(
        "Booking created | result=%s booking_id=%s payment_id=%s",
        result,
        getattr(booking, "booking_id", None),
        getattr(payment, "payment_id", None) if payment else None,
    )

    if payment and not getattr(booking, "payment", None):
        booking.payment = payment

    return build_booking_response(booking)


@app.get("/bookings/{booking_id}", response_model=BookingResponse)
async def get_booking(booking_id: str, db: Session = Depends(get_db)):
    booking = db.query(Booking).filter(Booking.booking_id == booking_id).first()
    if not booking:
        raise HTTPException(status_code=404, detail="Booking not found")
    return build_booking_response(booking)


@app.get("/users/{user_id}/bookings", response_model=List[BookingResponse])
async def list_user_bookings(user_id: str, db: Session = Depends(get_db)):
    bookings = (
        db.query(Booking)
        .filter(Booking.user_id == user_id)
        .order_by(Booking.created_at.desc())
        .all()
    )
    return [build_booking_response(booking) for booking in bookings]


@app.post("/refunds", response_model=RefundResponse, status_code=200)
async def request_refund(
    refund_request: RefundRequest,
    user_id: str = Query(..., description="User ID requesting the refund"),
    db: Session = Depends(get_db),
):
    result = await PaymentService.process_refund(
        db=db,
        booking_id=str(refund_request.booking_id),
        user_id=user_id,
        reason=refund_request.reason,
    )
    return RefundResponse(**result)


@app.websocket("/ws/events/{event_id}")
async def websocket_endpoint(websocket: WebSocket, event_id: str):
    await manager.connect(websocket, event_id)

    try:
        while True:
            data = await websocket.receive_text()
            if data == "ping":
                await websocket.send_text("pong")
            else:
                await manager.send_personal_message(
                    {"type": "echo", "message": data},
                    websocket,
                )
    except WebSocketDisconnect:
        manager.disconnect(websocket, event_id)
        logger.info("WebSocket disconnected for event %s", event_id)
    except Exception as exc:
        logger.error("WebSocket error for event %s: %s", event_id, exc)
        manager.disconnect(websocket, event_id)


@app.get("/ws/stats")
async def websocket_stats():
    return {
        "total_connections": manager.get_total_connections(),
        "connections_by_event": {
            event_id: manager.get_connection_count(event_id)
            for event_id in manager.active_connections.keys()
        },
    }


